def compute_largest_power(base: int, target_number: int, power: int) -> int:
    """ Return the highest power of a number (greater than 1) dividing given number,
    for example: 2**3 = 8, 2**5 = 32, 3**3 = 27. 
    """
    current_power = 1
    while base**current_power <= target_number:
        if base**current_power == target_number:
            return current_power
        current_power += 1

    return current_power - 1


def sum_all_squares(target_number: int) -> int:
    """ Given an integer n, it computes the sum of all squares below target number
    where every square should be multiple of base: target_number // base**k.
    """
    result = 0
    for base in range(2, 11):
        for i in range(1, compute_largest_power(base, target_number, 1) + 1):
            result += (i ** 2) * base**(i - 1)

    return result


