    """ Function checks if parenthesis group is balanced
    >>> is_balanced('((()))')
    True
    >>> is_balanced('(()')
    False
    """
    count = 0
    for char in group:
        if char == '(':
            count += 1
        elif char == ')':
            count -= 1
            if count < 0:
                return False
    return count == 0

